        betrag_kmep_o_fwu_kw_vj,
        betrag_kmep_o_fwu_ww,
        betrag_kmep_o_fwu_ww_vj,
        betrag_kmep_o_fwu_km,
        betrag_kmep_o_fwu_km_vj,
